278	    const unitSpan = axis.dataToCoord(tickValue + 1) - axis.dataToCoord(tickValue);
279	    const unitW = Math.abs(unitSpan * Math.cos(rotation));
280	    const unitH = Math.abs(unitSpan * Math.sin(rotation));
281	
282	    let maxW = 0;
283	    let maxH = 0;
284	
285	    // Caution: Performance sensitive for large category data.
286	    // Consider dataZoom, we should make appropriate step to avoid O(n) loop.
287	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
288	        let width = 0;
289	        let height = 0;
