296	        // Magic number
297	        width = rect.width * 1.3;
298	        height = rect.height * 1.3;
299	
300	        // Min size, void long loop.
301	        maxW = Math.max(maxW, width, 7);
302	        maxH = Math.max(maxH, height, 7);
303	    }
304	
305	    let dw = maxW / unitW;
306	    let dh = maxH / unitH;
307	    // 0/0 is NaN, 1/0 is Infinity.
308	    isNaN(dw) && (dw = Infinity);
309	    isNaN(dh) && (dh = Infinity);
310	    let interval = Math.max(0, Math.floor(Math.min(dw, dh)));
