318	    // otherwise the calculated interval might jitter when the zoom
319	    // window size is close to the interval-changing size.
320	    // For example, if all of the axis labels are `a, b, c, d, e, f, g`.
321	    // The jitter will cause that sometimes the displayed labels are
322	    // `a, d, g` (interval: 2) sometimes `a, c, e`(interval: 1).
323	    if (lastAutoInterval != null
324	        && lastTickCount != null
