import Axis from '../src/coord/Axis';
import Model from '../src/model/Model';
import IntervalScale from '../src/scale/Interval';
import TimeScale from '../src/scale/Time';
import { createAxisTicks, createAxisLabels } from '../src/coord/axisTickLabelBuilder';
import { AxisBaseModel } from '../src/coord/AxisBaseModel';
import { AxisBaseOption } from '../src/coord/axisCommonTypes';

function makeValueAxis(axisOption: AxisBaseOption, extent: [number, number]): Axis {
    const scale = new IntervalScale();
    scale.setExtent(extent[0], extent[1]);
    scale.calcNiceTicks();
    const axis = new Axis('x', scale, [0, 500]);
    axis.type = 'value';
    axis.model = new Model(axisOption) as unknown as AxisBaseModel;
    return axis;
}

function makeTimeAxis(axisOption: AxisBaseOption, extent: [number, number]): Axis {
    const scale = new TimeScale();
    scale.setExtent(extent[0], extent[1]);
    const axis = new Axis('x', scale, [0, 500]);
    axis.type = 'time';
    axis.model = new Model(axisOption) as unknown as AxisBaseModel;
    return axis;
}

describe('axis customValues ticks clipping with dataZoom', function () {

    it('filters custom ticks outside the zoomed scale extent', function () {
        // Simulates a dataZoom window of [3, 7] over an original extent of [0, 10].
        const axis = makeValueAxis({
            type: 'value',
            axisTick: { customValues: [0, 1.5, 3, 4.25, 7, 9, 10] }
        } as AxisBaseOption, [3, 7]);
        const result = createAxisTicks(axis, axis.getTickModel() as AxisBaseModel);
        expect(result.ticks).toEqual([3, 4.25, 7]);
    });

    it('filters custom labels outside the zoomed scale extent', function () {
        const axis = makeValueAxis({
            type: 'value',
            axisLabel: { customValues: [0, 1.5, 3, 4.25, 7, 9, 10] }
        } as AxisBaseOption, [3, 7]);
        const labels = createAxisLabels(axis).labels;
        expect(labels.map(label => label.tickValue)).toEqual([3, 4.25, 7]);
    });

    it('keeps all custom ticks when nothing is outside the extent', function () {
        const axis = makeValueAxis({
            type: 'value',
            axisTick: { customValues: [1.5, 4.25, 9] }
        } as AxisBaseOption, [0, 10]);
        const result = createAxisTicks(axis, axis.getTickModel() as AxisBaseModel);
        expect(result.ticks).toEqual([1.5, 4.25, 9]);
    });

    it('filters duplicated first/last time ticks outside the zoomed extent', function () {
        const t0 = +new Date('2024-01-01');
        const t1 = +new Date('2024-03-10');
        const t2 = +new Date('2024-06-15');
        const t3 = +new Date('2024-12-31');
        // Zoomed window [t1, t2]: out-of-window dates (and their
        // first/last duplicates) must not produce overflowing ticks.
        const axis = makeTimeAxis({
            type: 'time',
            axisTick: { customValues: [t0, t1, t2, t3] }
        } as AxisBaseOption, [t1, t2]);
        const result = createAxisTicks(axis, axis.getTickModel() as AxisBaseModel);
        // Time axis needs duplicate first/last tick (see TimeScale.getTicks()).
        expect(result.ticks).toEqual([t1, t1, t2, t2]);
        const labels = createAxisLabels(axis).labels;
        expect(labels.map(label => label.tickValue)).toEqual([t1, t1, t2, t2]);
    });

});

